357		\uses{def:submeasurement, def:approx_delta}
358		Let $A = \{A^x_a\}$, $B = \{B^x_a\}$, and $C = \{C^x_a\}$ be submeasurements such that $A^x_a \approx_{\delta} B^x_a$. Then
359		\begin{equation*}
360			\E_{\bx} \sum_a \bra{\psi} A^{\bx}_a  C^{\bx}_a \ket{\psi}
361			\approx_{\sqrt{\delta}} \E_{\bx} \sum_a \bra{\psi} B^{\bx}_a  C^{\bx}_a \ket{\psi}.
362		\end{equation*}
