364	\begin{proof}
365		\leanok
366		The difference has magnitude
367		\[
368			\Big| \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a) C^{\bx}_a \ket{\psi}\Big|.
369		\]
