371		\[
372			\Big(\E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a - B^{\bx}_a)^2 \ket{\psi}\Big)^{1/2}
373			\Big(\E_{\bx} \sum_a \bra{\psi} (C^{\bx}_a)^2 \ket{\psi}\Big)^{1/2}.
374		\]
