515			\approx_{2\sqrt\delta}
516			\E_x \sum_a \bra{\psi} B \ot A_a^x \ket{\psi}
517			\approx_{\sqrt\delta}
518			\E_x \sum_a \bra{\psi} BA_a^x \ot I \ket{\psi}.
