578	\begin{lemma}[Strong self-consistency and state-dependent distance]\label{prop:two-notions-of-self-consistency}
579		\lean{MIPStarRE.LDT.Preliminaries.twoNotionsOfSelfConsistency}
580		\leanok
581		\uses{def:strong-self-consistency, def:approx_delta}
582		If $A$ is $\delta$-strongly self-consistent, then
583		\[
584			A_a^x \ot I \approx_{2\delta} I \ot A_a^x.
585		\]
586		If $A$ is projective, the converse also holds.
587	\end{lemma}
588	\begin{proof}
589		\leanok
590		Expanding the squared norm gives
591		\begin{align}
592			      & \E_{\bx} \sum_a \lVert(A^{\bx}_a \otimes I - I \otimes A^{\bx}_a)\ket{\psi}\rVert^2 \nonumber                                                                  \\
593			=~    & 2\cdot \Big( \E_{\bx} \sum_a \bra{\psi} (A^{\bx}_a)^2 \otimes I \ket{\psi} -  \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi}\Big) \nonumber \\
594			\leq~ & 2\cdot \Big( \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes I \ket{\psi} -  \E_{\bx} \sum_a \bra{\psi} A^{\bx}_a \otimes A^{\bx}_a \ket{\psi}\Big).
595			\label{eq:here's-where-projectivity-would-help}
596		\end{align}
